import json
import os
import socket
import urllib.error
import urllib.request

# The internal price service. `prices.internal` is the canonical name; on
# networks where DNS for it is unavailable we fall back to the service's
# well-known cluster IP. All of these can be overridden via environment.
PRICES_HOST = os.environ.get("PRICES_HOST", "prices.internal")
PRICES_FALLBACK_IP = os.environ.get("PRICES_HOST_IP", "172.23.0.3")
PRICES_PORT = os.environ.get("PRICES_PORT", "8081")

# The service authenticates callers with an X-Pricing-Key header. The key is
# supplied by the environment (never hard-coded).
PRICING_KEY = os.environ.get("X_PRICING_KEY") or os.environ.get("PRICING_KEY")

# Current API version first, older version as compatibility fallback.
_API_PATHS = (
    os.environ.get("PRICES_API_PATH", "/api/v2/price"),
    "/api/v1/price",
)


def _resolvable(host: str) -> bool:
    try:
        socket.getaddrinfo(host, None)
        return True
    except OSError:
        return False


def _netloc() -> str:
    host = PRICES_HOST if _resolvable(PRICES_HOST) else PRICES_FALLBACK_IP
    return f"{host}:{PRICES_PORT}"


def _fetch(url: str) -> float:
    req = urllib.request.Request(url)
    if PRICING_KEY:
        req.add_header("X-Pricing-Key", PRICING_KEY)
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])


def get_price(sku: str) -> float:
    last_err = None
    for path in _API_PATHS:
        try:
            return _fetch(f"http://{_netloc()}{path}/{sku}")
        except urllib.error.HTTPError as e:
            last_err = e
            if e.code != 404:  # 401/500/etc: real response, don't retry
                raise
    raise last_err


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
